-- Auto-generated peatlands initialization script
CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS peatlands (
    ogc_fid SERIAL PRIMARY KEY,
    objectid INTEGER,
    layer_revi VARCHAR,
    shape_area DOUBLE PRECISION,
    geom GEOMETRY(Geometry, 4326)
);

CREATE INDEX IF NOT EXISTS peatlands_geom_geom_idx ON peatlands USING GIST (geom);

ON CONFLICT (ogc_fid) DO NOTHING;

SELECT setval('peatlands_ogc_fid_seq', COALESCE((SELECT MAX(ogc_fid) FROM peatlands), 1));
